args.sparql:
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?song ?performer ?performerLabel ?deathPlace ?deathPlaceLabel WHERE {
  ?song rdfs:label "I'll Come Running Back to You"@en .
  ?song a dbo:Song .
  OPTIONAL {
    ?song (dbo:artist|dbp:artist|dbo:performer|dbp:performer|dbp:writer|dbo:writer) ?performer .
  }
  OPTIONAL {
    ?performer (dbo:deathPlace|dbp:deathPlace) ?deathPlace .
  }
  OPTIONAL { ?performer rdfs:label ?performerLabel FILTER (lang(?performerLabel) = 'en') }
  OPTIONAL { ?deathPlace rdfs:label ?deathPlaceLabel FILTER (lang(?deathPlaceLabel) = 'en') }
}
LIMIT 20

